import React, {useState} from 'react';
import api from '../lib/api';
import { useNavigate } from 'react-router-dom';

export default function Login(){
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const nav = useNavigate();

  async function submit(e){
    e.preventDefault();
    setError('');
    try{
      const r = await api.post('/auth/login',{email, password});
      localStorage.setItem('hr_token', r.data.token);
      localStorage.setItem('hr_user', JSON.stringify(r.data.user));
      
      // Redirect based on is_admin
      if (r.data.user.is_admin) {
        nav('/admin/products');
      } else {
        nav('/');
      }
    }catch(err){
      const data = err.response?.data;
      let msg = 'Email atau password salah';
      if (data) {
        if (typeof data.message === 'string') msg = data.message;
        else if (data.message && typeof data.message === 'object') {
          const first = Object.values(data.message).flat?.() || Object.values(data.message);
          msg = Array.isArray(first) ? (first[0] || msg) : String(first || msg);
        } else if (typeof data.error === 'string') msg = data.error;
      }
      setError(msg);
    }
  }

  return (
    <div style={{maxWidth:400, margin:'80px auto', padding:20}}>
      <h2>Login</h2>
      <p style={{color:'#666', marginBottom:20}}>Login untuk melanjutkan belanja atau akses admin</p>
      {error && <div style={{color:'red', marginBottom:10}}>{error}</div>}
      <form onSubmit={submit}>
        <div style={{marginBottom:12}}>
          <label style={{display:'block', marginBottom:4}}>Email</label>
          <input 
            type="email"
            style={{width:'100%', padding:8, border:'1px solid #ddd'}} 
            value={email} 
            onChange={e=>setEmail(e.target.value)} 
            placeholder="email" 
            required
          />
        </div>
        <div style={{marginBottom:12}}>
          <label style={{display:'block', marginBottom:4}}>Password</label>
          <input 
            type="password" 
            style={{width:'100%', padding:8, border:'1px solid #ddd'}} 
            value={password} 
            onChange={e=>setPassword(e.target.value)} 
            placeholder="password" 
            required
          />
        </div>
        <div style={{marginBottom:12}}>
          <button type="submit" style={{width:'100%', padding:10, background:'#f27171', color:'#fff', border:'none', cursor:'pointer', borderRadius:4}}>
            Login
          </button>
        </div>
      </form>
      <div style={{textAlign:'center', marginTop:16}}>
        Belum punya akun? <a href="/register" style={{color:'#f27171'}}>Daftar Sekarang</a>
      </div>
    </div>
  )
}
